-- Netherstorm: combat SmartAI for 17 creatures that had no spells and no AI here. The rows are the 5.4.8 ones; the
-- spells they cast agree with the 3.3.5 SmartAI of the same creatures.

-- Netherstorm combat abilities
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (16948,16949,18864,18866,18867,18872,18873,18877,18880,18882,19494,19635,19830,19852,19881,20285,20332);
DELETE FROM `creature_text` WHERE `entry` IN (19635);
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (16948,16949,18864,18866,18867,18872,18873,18877,18880,18882,19494,19635,19830,19852,19881,20285,20332) AND `AIName` = '' AND `ScriptName` = '';
